using UnityEngine;

public class VariableDemo : MonoBehaviour
{
    int score = 100;
    float speed = 12.5f;
    string playerName = "Archer";
    bool isAlive = true;

    void Start()
    {
        Debug.Log($"Player: {playerName}, Score: {score}, Speed: {speed}, Alive: {isAlive}");

        score += 50;
        speed *= 2;
        isAlive = score > 0;

        Debug.Log($"Updated - Score: {score}, Speed: {speed}, Alive: {isAlive}");
    }
}
